// Horizon Power's four service areas, traced from its "Service area" poster as [longitude, latitude] points.
// Shapes run out past the coast and are clipped to the WA outline when drawn. Anything not covered (the south
// west, served by the South West Interconnected System) is left blank.
// "ngLands" is the variant that extends Esperance/Goldfields north along the border to take in the
// Ngaanyatjarra lands communities, which Horizon Power services from Esperance.
(function () {
  var kimberley = [[110, -10], [135, -10], [135, -21.0], [125.8, -21.0], [125.8, -19.76], [110, -19.76]];
  var pilbara = [[114.42, -19.76], [125.8, -19.76], [125.8, -21.0], [135, -21.0], [135, -23.47], [114.42, -23.47]];
  var gascoyneWest = [[110, -19.76], [114.42, -19.76], [114.42, -23.47]];
  var gascoyneSouth = [[120.85, -28.32], [120.85, -30.77], [120.52, -31.09], [113.9, -28.09], [110, -28.09]];
  var goldfieldsSouth = [[135, -36], [119.6, -36], [119.6, -34.51], [120.52, -33.82], [119.4, -32.03],
    [121.86, -30.77], [121.86, -29.98], [120.85, -29.98], [120.85, -28.32]];

  window.RC_REGION_SHAPES = {
    poster: {
      kimberley: kimberley,
      pilbara: pilbara,
      gascoyne: gascoyneWest.concat([[135, -23.47], [135, -28.32]], gascoyneSouth),
      goldfields: [[135, -28.32]].concat(goldfieldsSouth),
    },
    ngLands: {
      kimberley: kimberley,
      pilbara: pilbara,
      gascoyne: gascoyneWest.concat([[124.5, -23.47], [124.5, -27.0], [121.9, -27.0], [121.9, -28.32]], gascoyneSouth),
      goldfields: [[124.5, -23.47], [135, -23.47]].concat(goldfieldsSouth, [[121.9, -28.32], [121.9, -27.0], [124.5, -27.0]]),
    },
  };
  // Label spots, picked to sit clear of communities.
  window.RC_REGION_LABELS = {
    kimberley: [123.3, -19.35],
    pilbara: [119.6, -22.3],
    gascoyne: [116.6, -26.0],
    goldfields: [125.6, -31.2],
  };
})();

// Calibrated against the outline's known edges: the WA/NT border (129°E) sits at x = 577.9,
// the border meets the north coast (14.88°S) at y = 46.8 and the south coast (31.69°S) at y = 686.3.
// It is a plain equirectangular projection, so longitude is squashed by cos(~24.5°).
window.projectWA = function (lat, lng) {
  return {
    x: 577.9 - (129 - lng) * 34.6,
    y: 46.8 + (-14.88 - lat) * 38.04,
  };
};
